"""TS-5: every output states that it is an attorney work-product aid, not legal
advice, and that the attorney is responsible for it.

These strings live server-side and ride on the `done` event, so the banner the
UI paints and the text the clipboard carries come from one source and cannot
drift apart. A marking the user can copy out of is theatre (FR-23, FR-24).
"""

from __future__ import annotations

DRAFT_MARKING = (
    "UNREVIEWED AI DRAFT — generated by Legal Lens from the attorney’s own documents. "
    "Not legal advice. The attorney remains responsible for all content and must verify "
    "every citation before use."
)

OUTPUT_DISCLAIMER = (
    "Attorney work-product aid generated by Legal Lens. Not legal advice. "
    "Verify every citation against the source document."
)

INCOMPLETE_MARKING = (
    "INCOMPLETE OUTPUT — the response stream was interrupted and this text is partial."
)


def disclaimer_for(kind: str) -> str:
    return DRAFT_MARKING if kind == "draft" else OUTPUT_DISCLAIMER
